$post=$posts[$slug];$pageTitle=$post['title'];$pageDescription=$post['excerpt'];require __DIR__.'/includes/header.php';
$recent=array_filter($posts,fn($p,$k)=>$k!==$slug,ARRAY_FILTER_USE_BOTH);$recent=array_slice($recent,0,4,true);
?>
